// Turns the incoming email into a minimal PDF that the easybits Extractor can read.
// Pure JS, no dependencies, no external services. Paste as-is.

const email = $input.item.json;

const subject = email.subject || '(no subject)';
const from = email.from?.value?.[0]?.address || email.from?.text || 'unknown';
const date = email.date || '';
const body = email.text || email.snippet || '';

// Build the full text content that goes into the PDF
const rawContent = `Subject: ${subject}
From: ${from}
Date: ${date}

${body}`;

// PDF string escaping
const escapePdf = (str) =>
  str.replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');

// Wrap long lines so they don't overflow the page width (~90 chars at 10pt)
const lines = rawContent.split('\n').flatMap((line) => {
  if (line.length <= 90) return [line];
  const wrapped = [];
  for (let i = 0; i < line.length; i += 90) {
    wrapped.push(line.slice(i, i + 90));
  }
  return wrapped;
});

// Paginate: 55 lines per page at 10pt with reasonable margins
const LINES_PER_PAGE = 55;
const pages = [];
for (let i = 0; i < lines.length; i += LINES_PER_PAGE) {
  pages.push(lines.slice(i, i + LINES_PER_PAGE));
}
if (pages.length === 0) pages.push(['(empty email body)']);

// Build PDF content streams (one per page)
const buildContentStream = (pageLines) => {
  const textCommands = pageLines
    .map((line, idx) => {
      const y = 780 - idx * 14; // start near top, 14pt line height
      return `BT /F1 10 Tf 50 ${y} Td (${escapePdf(line)}) Tj ET`;
    })
    .join('\n');
  return `${textCommands}`;
};

// Construct PDF objects
const pdfObjects = [];

// 1: Catalog
pdfObjects.push(`<< /Type /Catalog /Pages 2 0 R >>`);

// 2: Pages tree (filled in after we know page object IDs)
// Placeholder — we'll come back to it

// 3+: Font, then page objects, then content streams
const fontObjId = 3;
pdfObjects.push(null); // reserve slot for Pages (object 2)
pdfObjects.push(`<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>`); // object 3

// Page + content stream pairs start at object 4
const pageObjectIds = [];
let nextObjId = 4;
for (const pageLines of pages) {
  const pageId = nextObjId++;
  const contentId = nextObjId++;
  pageObjectIds.push(pageId);

  const stream = buildContentStream(pageLines);

  pdfObjects.push(
    `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 ${fontObjId} 0 R >> >> /Contents ${contentId} 0 R >>`
  );
  pdfObjects.push(
    `<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`
  );
}

// Now build the Pages object (object 2)
const kids = pageObjectIds.map((id) => `${id} 0 R`).join(' ');
pdfObjects[1] = `<< /Type /Pages /Kids [${kids}] /Count ${pageObjectIds.length} >>`;

// Assemble the PDF file
let pdf = '%PDF-1.4\n';
const offsets = [0]; // object 0 is the free object, offset 0
for (let i = 0; i < pdfObjects.length; i++) {
  offsets.push(pdf.length);
  pdf += `${i + 1} 0 obj\n${pdfObjects[i]}\nendobj\n`;
}

const xrefOffset = pdf.length;
pdf += `xref\n0 ${pdfObjects.length + 1}\n`;
pdf += `+1234567890 f \n`;
for (let i = 1; i <= pdfObjects.length; i++) {
  pdf += `${String(offsets[i]).padStart(10, '0')} 00000 n \n`;
}
pdf += `trailer\n<< /Size ${pdfObjects.length + 1} /Root 1 0 R >>\n`;
pdf += `startxref\n${xrefOffset}\n%%EOF`;

// Return as binary
const buffer = Buffer.from(pdf, 'binary');

return {
  json: $input.item.json,
  binary: {
    bodyPdf: {
      data: buffer.toString('base64'),
      mimeType: 'application/pdf',
      fileName: 'email-body.pdf',
      fileExtension: 'pdf',
    },
  },
};

