(() => {
  const d = $json.data;
  const lines = [];
  if (d.vendor) lines.push(`Vendor: ${d.vendor}`);
  if (d.confirmation_number) lines.push(`Confirmation: ${d.confirmation_number}`);
  if (d.participants) lines.push(`Participants: ${d.participants}`);
  if (d.notes) lines.push('', 'Notes:', d.notes);
  lines.push('', '— Original Email —', $json.archive_link);
  lines.push('', `Auto-imported by easybits Extractor • ${new Date().toISOString().split('T')[0]}`);
  return lines.join('\n');
})()
}}

