// Splits Gmail attachments into one item per PDF/image.
// If there are no usable attachments, returns an empty array — the
// downstream Extractor + Merge will naturally produce no attachment
// extractions, and the body branch carries the workflow alone.

const item = $input.first();
const results = [];

if (!item.binary) return results;

for (const [key, binary] of Object.entries(item.binary)) {
  const mime = binary.mimeType || '';
  // Only process PDFs and images — easybits-compatible formats
  if (!mime.startsWith('application/pdf') && !mime.startsWith('image/')) {
    continue;
  }

  results.push({
    json: {
      attachmentKey: key,
      attachmentMime: mime,
      attachmentName: binary.fileName || key,
    },
    binary: {
      attachment: binary,
    },
  });
}

return results;

// Merges extractions from the body branch and the attachment branch.
// Strategy: collect every extraction's `data` object, then for each
// field take the first non-null value found.
//
// Priority: ATTACHMENTS WIN OVER BODY.
// Attachments are the authoritative source (actual ticket/invoice PDF).
// The body is fallback context — used only to fill gaps where the
// attachment didn't have a value. This prevents email signatures or
// promotional content from polluting fields the attachment got right.

const allExtractions = [];

// 1. Attachments first (highest priority)
for (const item of $input.all()) {
  if (item.json?.data) {
    allExtractions.push(item.json.data);
  }
}

// 2. Body extraction last (fallback)
const bodyExt = $('Extractor: Email Body').first();
if (bodyExt?.json?.data) {
  allExtractions.push(bodyExt.json.data);
}

const fields = [
  'event_type', 'title', 'start_datetime', 'end_datetime',
  'location', 'confirmation_number', 'vendor', 'notes',
  'participants',
];

const isMissing = (v) =>
  v === null ||
  v === undefined ||
  v === '' ||
  (typeof v === 'string' && v.trim().toLowerCase() === 'null');

const merged = {};
for (const field of fields) {
  merged[field] = null;
  for (const extraction of allExtractions) {
    if (!isMissing(extraction[field])) {
      merged[field] = extraction[field];
      break;
    }
  }
}

return [{ json: { data: merged } }];
